window.addEventListener('DOMContentLoaded',()=>{'use strict';
const $=id=>document.getElementById(id),flow=$('flow'),F=GlyphFlow.model,C=GlyphFlow.core,wordForm=$('word-form'),workspace=new GlyphFlow.Document(flow,{insetTop:130}),auth=window.GLYPH_BRIDGE;
let revision=0,dirty=false,editing=false,suppress=false,remoteCall=false,polling=false,ready=!auth,owner=crypto.randomUUID(),saveChain=Promise.resolve(),sequence=0,wordId=null,lastClusterWord=null;const clusterBadge=document.createElement('div');clusterBadge.className='receive-badge';const receiveBadge=document.createElement('div');receiveBadge.className='receive-badge';
const report=e=>$('status').textContent=e.message||String(e);
async function api(route,body){const response=await fetch('/api/'+route,{method:body?'POST':'GET',headers:{Authorization:'Bearer '+auth.token,'Content-Type':'application/json'},...(body?{body:JSON.stringify(body)}:{})});const data=await response.json();if(!response.ok)throw Error(data.error?.message||'Flow request failed.');return data;}
function adopt(saved){const doc=C.json(saved.flow),source=doc.components.find(n=>n.id==='source');let upgraded=false;if(source?.layout.type==='sphere'&&Array.isArray(source.state)){for(const [key,value] of Object.entries({reflow:true,shatterAt:180,reflowDuration:2.8}))if(source.layout[key]===undefined){source.layout[key]=value;upgraded=true;}if(!source.methods.shuffle){source.methods.shuffle=C.json(F.defaultDocument().components[0].methods.shuffle);source.methods.shuffle.output=source.stateContract;upgraded=true;}}suppress=true;try{workspace.load(doc);revision=saved.revision;dirty=upgraded;$('sync-state').textContent='SAVED / REV '+revision;}finally{suppress=false;}if(upgraded&&ready)markDirty();}
function editor(force=false){if(force||!editing)$('flow-json').value=JSON.stringify(workspace.document,null,2);}
let arrayKey='';
function geometryInfo(){const source=workspace.document?.components.find(n=>n.id==='source'),node=flow.nodes.find(n=>n.id==='source');if(!source||!node)return;const rows=F.selectItems(source.state),chars=F.characterCount(source.state,source.layout),shattered=source.layout.type==='sphere'&&source.layout.reflow&&!!source.layout.shatterAt&&chars>source.layout.shatterAt,active=node.geometry.active;node.toggleAttribute('data-reorganizing',active);node.toggleAttribute('data-shattered',!!shattered);$('geometry-state').textContent=(active?'REORGANIZING':shattered?'LETTERS ON SHELL':source.layout.type==='sphere'?'WORDS ON SHELL':'SOURCE ARRAY')+' / '+chars+' CHARACTERS'+(source.layout.shatterAt?' / LIMIT '+source.layout.shatterAt:'');for(const id of ['shuffle-source','shuffle-seed','shatter-enabled','shatter-limit','geometry-duration'])$(id).disabled=remoteCall||!ready||editing||flow.flights.size>0||active||source.layout.type!=='sphere'||(id==='shuffle-source'&&!source.methods.shuffle);const key=C.canonical(rows);if(arrayKey!==key){arrayKey=key;$('array-order').replaceChildren(...rows.map((row,i)=>{const li=document.createElement('li'),index=document.createElement('span');index.textContent=String(i).padStart(2,'0');li.append(index,document.createTextNode(String(row?.[source.layout.label||'title']??row)));return li;}));}if(!wordId)receiveBadge.textContent=(active?'WEAVING / ':shattered?'SHATTERED / ':'ARRAY / ')+rows.length+' ENTRIES / '+chars+' CHARS';}
function geometrySettings(){const source=workspace.document?.components.find(n=>n.id==='source');if(!source)return;$('shatter-enabled').checked=!!source.layout.shatterAt;$('shatter-limit').value=source.layout.shatterAt||180;$('geometry-duration').value=source.layout.reflowDuration??2.8;$('geometry-duration-label').value=Number($('geometry-duration').value).toFixed(1)+'s';}
function update(){const snapshot=flow.snapshot;$('flight-count').textContent=snapshot.flights.length+' IN FLIGHT';$('state').textContent=JSON.stringify({revision,components:workspace.document?.components.map(n=>({id:n.id,state:n.state})),receipts:snapshot.receipts},null,2);$('invoke').disabled=remoteCall||!ready;const source=workspace.document?.components.find(n=>n.id==='source');$('word-send').disabled=remoteCall||!ready||!!wordId||!source?.methods.add;$('word-input').disabled=!!wordId;for(const id of ['word-travel','word-receive','word-duration'])$(id).disabled=remoteCall||!ready||!!wordId||snapshot.flights.length>0||editing||!source?.methods.add;if(source&&!wordId){const count=F.selectItems(source.state).length;receiveBadge.textContent=receiveBadge.textContent.startsWith('STORED /')?receiveBadge.textContent.replace(/\d+ ENTRIES$/,count+' ENTRIES'):'ARRAY / '+count+' ENTRIES';}const route=workspace.document?.connections.find(e=>e.from==='source'&&e.to==='cluster'),sourceNode=flow.nodes.find(n=>n.id==='source');if(sourceNode)sourceNode.markInteractionDisabled=remoteCall||!ready||!!(route&&workspace.pending.has(route.id));const cluster=flow.nodes.find(n=>n.id==='cluster');if(cluster){const processing=[...flow.flights.values()].find(p=>p.to==='cluster'&&p.phase==='processing');cluster.toggleAttribute('data-receiving',!!processing);const rows=F.selectItems(cluster.value);if(processing){const records=Array.isArray(processing.payload)?processing.payload:[processing.payload];clusterBadge.textContent=records.length===1?'CLASSIFYING / '+records[0].category:'CLASSIFYING / '+records.length+' RECORDS';}else clusterBadge.textContent=lastClusterWord&&rows.some(r=>r.id===lastClusterWord.id)?'FILED / '+lastClusterWord.title+' / '+lastClusterWord.category:rows.length+' RECORDS / GROUPED BY CATEGORY';}for(const b of $('connections').children)b.disabled=remoteCall||!ready;geometryInfo();editor();}
function methodOptions(){const doc=workspace.document,selected=$('method-component').value||doc.components[0].id,old=$('method-name').value||'add';const n=doc.components.find(n=>n.id===selected)||doc.components[0];$('method-name').replaceChildren(...Object.keys(n.methods).map(name=>new Option(name,name)));if(n.methods[old])$('method-name').value=old;methodInfo();}
function methodInfo(){const n=workspace.document.components.find(n=>n.id===$('method-component').value),name=$('method-name').value,m=n.methods[name];$('invoke').textContent='Invoke '+n.id+'.'+name+' ↗';$('method-contract').textContent=JSON.stringify({input:F.resolveContract(workspace.document,m.input),result:F.resolveContract(workspace.document,m.output),interaction:C.interaction(m.interaction)},null,2);}
function controls(){geometrySettings();const doc=workspace.document,selected=$('method-component').value;$('method-component').replaceChildren(...doc.components.map(n=>new Option(n.title+' / '+n.id,n.id)));if(doc.components.some(n=>n.id===selected))$('method-component').value=selected;methodOptions();const source=doc.components.find(n=>n.id==='source');wordForm.style.left=(source?.position.x??1)+'%';wordForm.style.width=(source?.position.width??25)+'%';flow.append(wordForm);if(source){const behavior=C.interaction(source.methods.add?.interaction);$('word-travel').value=behavior.travel;$('word-receive').value=behavior.receive;$('word-duration').value=behavior.duration;$('word-duration-label').value=behavior.duration.toFixed(1)+'s';const node=flow.node('source');node.append(receiveBadge);node.setAttribute('mark-action','Send to Category clusters');node.querySelector('.node-foot').textContent='CLICK A WORD → CATEGORY CLUSTERS';if(!wordId)receiveBadge.textContent='ARRAY / '+F.selectItems(node.value).length+' ENTRIES';}const cluster=flow.nodes.find(n=>n.id==='cluster');if(cluster)cluster.append(clusterBadge);if(!ready){const source=doc.components.find(n=>n.id==='source'),ids=new Set(F.selectItems(source?.state).map(r=>r?.id));let number=13;while(ids.has('r'+number))number++;$('method-payload').value=JSON.stringify({id:'r'+number,title:'New signal',category:'SIGNAL'},null,2);}$('connections').replaceChildren(...doc.connections.map((e,i)=>{const b=document.createElement('button');b.id=i===0?'send':i===1?'forward':e.id;b.textContent=e.title+' ↗';b.onclick=()=>{if(remoteCall)return;workspace.run(e.id).then(r=>{report('Arrived at '+r.to+'.'+r.method+' · receiving state committed.');}).catch(report);};return b;}));update();}
workspace.addEventListener('document',controls);
flow.addEventListener('glyph-activate',async e=>{if(e.detail.component!=='source'||remoteCall||!ready)return;const route=workspace.document.connections.find(link=>link.from==='source'&&link.to==='cluster');if(!route){report('Connect Source field to Category clusters before sending a word.');return;}const source=flow.node('source'),row=source.value.find(row=>String(row.id)===e.detail.mark),focused=source.shadowRoot.activeElement;if(!row)return;try{await workspace.run(route.id,{mark:e.detail.mark});lastClusterWord=row;report('“'+row.title+'” found its place in '+row.category+'. Source keeps its copy.');}catch(error){report(error);}finally{update();if(focused?.isConnected&&document.activeElement===document.body)focused.focus({preventScroll:true});}});

function markDirty(){if(suppress||remoteCall)return;dirty=true;$('sync-state').textContent=auth?'SAVING…':'LOCAL DOCUMENT';if(auth)scheduleSave();}
workspace.addEventListener('change',()=>{update();markDirty();});
function scheduleSave(){saveChain=saveChain.catch(()=>{}).then(async()=>{if(!dirty||remoteCall||!ready)return;const value=workspace.document;dirty=false;try{const result=await api('tool',{name:'glyph_flow_apply',arguments:{flow_json:JSON.stringify(value),expected_revision:revision}});revision=result.revision;$('sync-state').textContent='SAVED / REV '+revision;}catch(e){dirty=true;$('sync-state').textContent='SYNC CONFLICT';report(e);throw e;}});saveChain.catch(()=>{});return saveChain;}
async function flush(){if(!ready)throw Error('The saved flow is still loading.');if(editing)throw Error('Apply or reload the flow document before prompting.');if(remoteCall||flow.snapshot.flights.length)throw Error('Wait for the current transfer to arrive before prompting.');if(auth){await scheduleSave();const saved=await api('flow');if(C.canonical(saved.flow)!==C.canonical(workspace.document))throw Error('The flow has changed elsewhere. Reload the current document before prompting.');revision=saved.revision;}}
window.glyphFlowStudio={workspace,flush,get revision(){return revision;}};
$('method-component').onchange=methodOptions;$('method-name').onchange=methodInfo;
$('method-payload').value=JSON.stringify({id:'r13',title:'New signal',category:'SIGNAL'},null,2);
function applyInteraction(){if(remoteCall||!ready||wordId||flow.snapshot.flights.length||editing)return;try{const focused=document.activeElement,doc=workspace.document,node=doc.components.find(n=>n.id==='source');node.methods.add.interaction={travel:$('word-travel').value,receive:$('word-receive').value,duration:Number($('word-duration').value),textField:'title'};workspace.load(doc);if(focused?.isConnected)focused.focus({preventScroll:true});markDirty();report('Updated source.add interaction. Existing content is preserved.');}catch(e){report(e);}}
$('word-travel').onchange=$('word-receive').onchange=$('word-duration').onchange=applyInteraction;$('word-duration').oninput=()=>$('word-duration-label').value=Number($('word-duration').value).toFixed(1)+'s';
function geometryAvailable(){if(remoteCall||!ready||editing||flow.flights.size||flow.node('source').geometry.active)throw Error('Wait for the current motion, or apply your document changes first.');}
$('shuffle-source').onclick=()=>{try{geometryAvailable();const seed=Number($('shuffle-seed').value);if(!$('shuffle-seed').value||!Number.isInteger(seed)||seed<0||seed>4294967295)throw Error('Use a whole-number seed from 0 to 4294967295.');$('geometry-settings').open=false;flow.node('source').dispatch('shuffle',{seed});report('source.shuffle({seed:'+seed+'}) reordered the array. Only its geometry is moving.');}catch(e){report(e);}};
function applyGeometry(){try{geometryAvailable();const enabled=$('shatter-enabled').checked,limit=Number($('shatter-limit').value);if(!Number.isInteger(limit)||limit<1||limit>4096)throw Error('Character limit must be a whole number from 1 to 4096.');workspace.configureLayout('source',{reflow:true,shatterAt:enabled?limit:0,reflowDuration:Number($('geometry-duration').value)});markDirty();report(enabled?'Source geometry shatters above '+limit+' total characters.':'Source letters are re-forming their words.');}catch(e){geometrySettings();report(e);}}
$('shatter-enabled').onchange=$('shatter-limit').onchange=$('geometry-duration').onchange=applyGeometry;$('geometry-duration').oninput=()=>$('geometry-duration-label').value=Number($('geometry-duration').value).toFixed(1)+'s';
flow.addEventListener('glyph-geometry',e=>{if(e.detail.component==='source')queueMicrotask(update);});
$('word-form').onsubmit=async e=>{e.preventDefault();if(remoteCall||!ready||wordId)return;const word=$('word-input').value.trim();if(!word){$('word-status').textContent='Enter a word first.';return;}let node;try{node=flow.node('source');const rect=$('word-input').getBoundingClientRect(),world=flow.getBoundingClientRect(),record={id:'w-'+crypto.randomUUID().slice(0,16),title:word,category:'SIGNAL'};wordForm.querySelector('details').open=false;wordId='word-'+owner+'-'+(++sequence);wordForm.dataset.phase='traveling';$('word-status').textContent='Hopping to source.add…';update();const receipt=await node.api.add(record,{id:wordId,origin:{x:rect.left-world.left+rect.width/2,y:rect.bottom-world.top+3}});wordForm.dataset.phase='stored';$('word-status').textContent='“'+word+'” found its place.';receiveBadge.textContent='STORED / '+word+' / '+F.selectItems(node.value).length+' ENTRIES';$('word-input').value='';report('source.add accepted “'+word+'”. The array now has '+F.selectItems(node.value).length+' entries.');}catch(error){wordForm.dataset.phase='rejected';receiveBadge.textContent='NOT STORED / '+word;$('word-status').textContent=error.message;report(error);}finally{node?.removeAttribute('data-receiving');wordId=null;update();$('word-input').focus();}};
$('method-form').onsubmit=async e=>{e.preventDefault();if(remoteCall||!ready)return;try{const node=flow.node($('method-component').value),method=$('method-name').value,input=JSON.parse($('method-payload').value),receipt=await node.invoke(method,input,{id:'local-'+owner+'-'+(++sequence)});report('Arrived at '+receipt.to+'.'+receipt.method+' · typed result: '+JSON.stringify(receipt.result));}catch(error){report(error);}};
$('pause').onclick=()=>{flow.toggleAttribute('paused');$('pause').textContent=flow.hasAttribute('paused')?'Resume':'Pause';};
$('reset').onclick=()=>{if(remoteCall){report('Wait for the claimed method call to finish.');return;}workspace.reset();report('Restored each component’s initial content.');};
$('flow-json').oninput=()=>{editing=true;$('document-status').textContent='Unapplied document changes.';};
$('validate-document').onclick=()=>{try{const result=F.audit(JSON.parse($('flow-json').value));$('document-status').textContent=result.valid?'Valid flow, interfaces and current data.':result.errors.join(' ');}catch(e){$('document-status').textContent=e.message;}};
$('apply-document').onclick=()=>{if(remoteCall){report('Wait for the claimed method call to finish.');return;}try{workspace.load(JSON.parse($('flow-json').value));editing=false;editor(true);markDirty();$('document-status').textContent='Applied validated document.';}catch(e){$('document-status').textContent=e.message;}};
$('revert-document').onclick=async()=>{try{if(remoteCall)throw Error('Wait for the claimed call to finish.');if(auth)adopt(await api('flow'));editing=false;editor(true);$('document-status').textContent='Loaded the current flow.';}catch(e){report(e);}};
$('clear-receipts').onclick=async()=>{try{if(remoteCall||flow.snapshot.flights.length)throw Error('Wait for active transfers before clearing receipts.');if(auth)await api('flow/receipts/reset',{});flow.receipts.clear();update();report('Cleared settled receipts. Use fresh invocation IDs for new calls.');}catch(e){report(e);}};
flow.addEventListener('glyph-transfer',e=>{if(e.detail.to==='cluster'&&e.detail.status==='arrived'&&Array.isArray(e.detail.result)&&e.detail.result.length===1)lastClusterWord=e.detail.result[0];if(e.detail.id===wordId&&e.detail.status==='processing'){wordForm.dataset.phase='processing';$('word-status').textContent='Source is sorting pixels…';flow.node('source').setAttribute('data-receiving','');receiveBadge.textContent='RECEIVING / PIXEL SORT';}if(e.detail.status==='processing')report('Receiving → '+e.detail.to+'.'+e.detail.method+'. Processing before commit.');if(e.detail.status==='started')report('In transit → '+e.detail.to+'.'+(e.detail.method||'receive')+'. State waits for arrival.');update();});flow.addEventListener('glyph-flow-error',e=>report(e.detail));
async function poll(){if(!auth||polling||!ready||document.hidden||dirty||remoteCall||editing)return;polling=true;try{await saveChain;const saved=await api('flow');if(dirty||remoteCall||editing)return;if(saved.revision!==revision){adopt(saved);report('Loaded the designer’s validated flow proposal.');}if(flow.snapshot.flights.length||!saved.calls.some(c=>c.status==='queued'))return;remoteCall=true;update();const claimed=await api('flow/claim',{owner});if(!claimed.command)return;if(claimed.revision!==revision)adopt(await api('flow'));const call=claimed.command,base=claimed.revision;try{await flow.node(call.component).invoke(call.method,call.payload,{id:call.id});const result=await api('flow/complete',{id:call.id,owner,expected_revision:base,flow_json:JSON.stringify(workspace.document)});revision=result.revision;$('sync-state').textContent='SAVED / REV '+revision;report('Designer call arrived: '+call.component+'.'+call.method+' · receipt committed.');}catch(e){try{await api('flow/complete',{id:call.id,owner,error:e.message});}catch{}adopt(await api('flow'));report(e);}finally{remoteCall=false;update();}}catch(e){report(e);}finally{remoteCall=false;update();polling=false;}}
workspace.load(F.defaultDocument());editor(true);
if(auth){api('flow').then(saved=>{adopt(saved);ready=true;if(dirty)scheduleSave();update();report('Connected. Invoke a method, send content, or prompt the Studio Designer.');}).catch(report);setInterval(poll,700);}else{report('Standalone flow. Changes stay in this page.');update();}
});
